asio::awaitable<void> receiver(tcp::socket sock) {
  std::array<char, 4> hdr{};
  for (;;) {
    co_await asio::async_read(sock, asio::buffer(hdr), asio::use_awaitable);
    std::string body(decode_length(hdr), '\0');
    co_await asio::async_read(sock, asio::buffer(body), asio::use_awaitable);
    dispatch(decode(body));                            // peer method
  }
}
